import csv
from io import StringIO

def solve(x):
    if not x.strip():
        return []

    rows = x.strip().splitlines()
    reader = csv.DictReader(StringIO(rows))
    values = {}

    for row in reader:
        label = row['label']
        value = int(row['value'])
        values[label] = value

    result = []
    for label in values:
        if values[label] >= 5:
            result.append(label)

    return result
