import re

def solve(x):
    events = []
    for line in x.strip().split('\n'):
        if line.strip() and not line.startswith('['):
            key, value = line.split('=')
            events.append((key.strip(), int(value.strip())))

    alerts = []
    label_runs = {}

    for label, value in events:
        if label not in label_runs:
            label_runs[label] = [value]
        else:
            label_runs[label].append(value)

        if len(label_runs[label]) >= 2:
            if len(label_runs[label]) >= 4:
                alerts.append(label)
            if value < label_runs[label][-1]:
                label_runs[label] = [value]

    return alerts
